    {
        ($this->run)(DnsSpec::REMOVE_ZONE_KEY, ['domain' => $domain, 'keyId' => $keyId]);
    }

    /**
     * Delete DNS zone record.
     *
     * This function deletes a DNS zone record.
     *
     * Documented: Available from cPanel & WHM 11 (x-cpanel-available-version).
     *
     * Documented: Deletes a DNS zone record. Incorrect removal can make domains resolve incorrectly. Disabling the DNS
     * role disables this function, and it cannot modify temporary domains.
     *
     * Documented: Source-based line conversion: parseDnsZone() returns zero-based line_index, while removeZoneRecord()
     * requires the one-based zone-file line. Pass line_index + 1, never line_index directly; for example, index 3
     * requires line 4. This follows Cpanel/ZoneFile/Parse.pm and the WHM zone-file Line handling reviewed on
     * 11.138.0.19, not a live removal. Omitting serialnum uses the current zone serial number.
     *
     * API-map identity: whm1:removezonerecord#GET (wire name removezonerecord; DNS Zones).
     *
     * @param int $line The DNS zone record file's line number.
     * @param string $zone The zone record's domain.
     * @param string|null $serialnum The zone file's serial number. Null omits it.
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/dns-zones/dns-removezonerecord
     */
    public function removeZoneRecord(int $line, string $zone, ?string $serialnum = null): void
    {
        ($this->run)(DnsSpec::REMOVEZONERECORD, ['line' => $line, 'zone' => $zone, 'serialnum' => $serialnum]);
    }

    /**
     * Restore DNS zone to default values.
     *
     * This function resets a DNS zone to its default values. This also resets the domain's subdomain DNS records, and
     * restores zone file subdomains in the server's `httpd.conf` file. For example, use this function to restore DNS
     * zones that are corrupt.
     *
     * Documented: Available from cPanel & WHM 11 (x-cpanel-available-version).
     *
     * Documented: This function resets a DNS zone to its default values. This also resets the domain's subdomain DNS
     * records, and restores zone file subdomains in the server's `httpd.conf` file. For example, use this function to
     * restore DNS zones that are corrupt. **Note:** Zone resets preserve valid TXT records, but **all** other records
     * will return to their default values. **Important:** When you disable the [DNS
     * role](https://go.cpanel.net/serverroles), the system **disables** this function. **Note** You **must** include
     * either the `domain` or the `zone` parameters.
     *
     * Documented: At least one selector, domain or zone, is required by the upstream contract even though both formal
     * parameters are optional. Resetting is destructive: valid TXT records are preserved, all other records return to
     * defaults, subdomain records reset and zone file subdomains are restored in httpd.conf.
     *
     * Policy: Client behavior: supply domain or zone explicitly before calling resetZone(). The client does not choose
     * a selector, back up the zone, roll changes back or retry automatically.
     *
     * API-map identity: whm1:resetzone#GET (wire name resetzone; Domain Management).
     *
     * @param string|null $domain The domain. Null omits it.
     * @param string|null $user The domain's owner. Null omits it.
     * @param string|null $zone The zone file. Null omits it.
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/domain-management/dns-resetzone
     */
    public function resetZone(?string $domain = null, ?string $user = null, ?string $zone = null): void
    {
        ($this->run)(DnsSpec::RESETZONE, ['domain' => $domain, 'user' => $user, 'zone' => $zone]);
    }

