    /**
     * Create mail exchanger record.
     *
     * This function creates a new MX record.
     *
     * Documented: Available from cPanel & WHM 11.28 (x-cpanel-available-version).
     *
     * Documented: This function creates a new MX record. **Important:** When you disable the [DNS
     * role](https://go.cpanel.net/howtouseserverprofiles#roles), the system **disables** this function.
     *
     * Documented: Omitting class retains IN and omitting ttl retains 14400 seconds. Lower preference values have higher
     * MX priority. This creates a record immediately; no retry or rollback is provided.
     *
     * API-map identity: whm1:savemxs#GET (wire name savemxs; Domain Management).
     *
     * @param string $domain The zone record's domain.
     * @param string $exchange The domain's mail exchanger.
     * @param string $name The record name.
     * @param int $preference The MX record's priority order.
     * @param string|null $class The record's class. Null omits it.
     * @param int|null $ttl The record's Time To Live (TTL) in seconds. Null omits it.
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/domain-management/dns-savemxs
     */
    public function saveMxs(
        string $domain,
        string $exchange,
        string $name,
        int $preference,
        ?string $class = null,
        ?int $ttl = null,
    ): void {
        ($this->run)(DnsSpec::SAVEMXS, [
            'domain' => $domain,
            'exchange' => $exchange,
            'name' => $name,
            'preference' => $preference,
            'class' => $class,
            'ttl' => $ttl,
        ]);
    }

    /**
     * Update remote DNS server's nameserver software.
     *
     * This function sets the nameserver software that the remote servers in a DNS cluster run. The system queues the
     * nameserver software that you select until the HTTP request finishes. Then, it sets the remote servers' nameserver
     * software.
     *
     * Documented: Available from cPanel & WHM 84 (x-cpanel-available-version).
     *
     * Documented: This function sets the nameserver software that the remote servers in a DNS cluster run. The system
     * queues the nameserver software that you select until the HTTP request finishes. Then, it sets the remote servers'
     * nameserver software.
     *
     * Documented: The input names are BIND, PowerDNS or Disabled; returned names are lowercase. A queued message is not
     * completion evidence. The client performs no polling or retry.
     *
     * API-map identity: whm1:set_nameserver#GET (wire name set_nameserver; DNS Cluster Settings).
     *
     * @param 'BIND'|'PowerDNS'|'Disabled' $nameserver The nameserver software.
     * @return SetNameserverResult
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @throws PayloadMismatchException If the API envelope reported success but the payload differs from the contract;
     *     the operation may already have changed state; do not retry automatically.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/dns-cluster-settings/nameserver-set_nameserver
     */
    public function setNameserver(string $nameserver): array
    {
        /** @var SetNameserverResult $result Validated against DnsSpec::SET_NAMESERVER. */
        $result = ($this->run)(DnsSpec::SET_NAMESERVER, ['nameserver' => $nameserver]);

        return $result;
    }

    /**
     * Enable NSEC3 semantics for domain.
     *
     * This function configures the domain to use Next Secure Record 3 (NSEC3) semantics.
     *
     * Documented: Available from cPanel & WHM 86 (x-cpanel-available-version).
     *
     * Documented: This function configures the domain to use [Next Secure Record
     * 3](https://tools.ietf.org/html/rfc4470) (NSEC3) semantics. **Note:** Only servers that run PowerDNS can use
     * DNSSEC. If you call this function on a server that doesn't use PowerDNS, you will receive an error.
     *
     * Documented: nsec3_iterations is 0 through 500; nsec3_narrow=1 is Narrow and 0 Inclusive mode. nsec3_opt_out=1
     * creates records for all delegations and 0 only secure delegations. nsec3_salt is passed unchanged. Inspect domain
     * enabled/error outcomes separately from metadata.
     *
     * API-map identity: whm1:set_nsec3_for_domains#GET (wire name set_nsec3_for_domains; Domain Management).
     *
     * @param string $domain The domain for which to enable NSEC3 semantics.
     * @param int $nsec3Iterations The number of times that the system re-executes the first resource record hash
     *     operation.
     * @param bool $nsec3Narrow Whether NSEC3 will operate in Narrow mode or Inclusive mode.
     * @param bool $nsec3OptOut Whether the system will create records for all delegations.
     * @param string $nsec3Salt The salt value that PowerDNS uses in the hashes.
     * @return SetNsec3ForDomainsResult
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @throws PayloadMismatchException If the API envelope reported success but the payload differs from the contract;
     *     the operation may already have changed state; do not retry automatically.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/domain-management/dns-set_nsec3_for_domains
     */
    public function setNsec3ForDomains(
        string $domain,
        int $nsec3Iterations,
        bool $nsec3Narrow,
        bool $nsec3OptOut,
        string $nsec3Salt,
    ): array {
        /** @var SetNsec3ForDomainsResult $result Validated against DnsSpec::SET_NSEC3_FOR_DOMAINS. */
        $result = ($this->run)(DnsSpec::SET_NSEC3_FOR_DOMAINS, [
            'domain' => $domain,
            'nsec3Iterations' => $nsec3Iterations,
            'nsec3Narrow' => $nsec3Narrow,
            'nsec3OptOut' => $nsec3OptOut,
            'nsec3Salt' => $nsec3Salt,
        ]);

        return $result;
    }

